extern stringx ksGlobalTextArray[];
enum { GT_IGO_FT = 261 };
void *operator new(unsigned int, unsigned int, const char *, int);
#define NULL 0
#define NEW new(0,__FILE__,__LINE__)

class WaveIndicatorWidget : public IGOWidget
{
public:
    enum STATE { STATE_NONE, STATE_DIR, STATE_SURGE, STATE_TONGUE, STATE_HILITE_NONE, STATE_HILITE_FACE, STATE_HILITE_LIP, STATE_HILITE_TUBE };
private:
    enum { NUM_WAVES = 3 };
    enum { NUM_TONGUES = 6 };
    PanelQuad *wavePQ[2][NUM_WAVES];
    PanelQuad *arrowPQ[2];
    PanelQuad *tonguePQ[2][NUM_TONGUES];
    PanelQuad *hilitePQ[2][3];
    PanelQuad *heightPQ;
    TextString *heightText;
    TextString *unitText;
    TextString *nextHeightText;
    TextString *nextUnitText;
    int dirIdx;
    float waveIdx;
    float tongueIdx;
    float hiliteTime;
    float fade;
    int fadeDir;
    STATE state;
public:
    WaveIndicatorWidget();
};

WaveIndicatorWidget::WaveIndicatorWidget()
{
	for (int d = 0; d < 2; d++)
	{
		for (int i = 0; i < NUM_WAVES; i++)
			wavePQ[d][i] = NULL;

		for (int i = 0; i < NUM_TONGUES; i++)
			tonguePQ[d][i] = NULL;

		hilitePQ[d][0] = NULL;
		hilitePQ[d][1] = NULL;
		hilitePQ[d][2] = NULL;

		arrowPQ[d] = NULL;
	}
	heightPQ = NULL;

	heightText = NEW TextString(NULL, "13.3", 405, 423, 10, 0.80f, Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, color32(255, 255, 255, 255));
	unitText = NEW TextString(NULL, ksGlobalTextArray[GT_IGO_FT], 406, 423, 10, 0.60f, Font::HORIZJUST_LEFT, Font::VERTJUST_BOTTOM, color32(255, 255, 255, 255));
	nextHeightText = NEW TextString(NULL, "19.9", 406, 394, 10, 0.65f, Font::HORIZJUST_RIGHT, Font::VERTJUST_BOTTOM, color32(255, 255, 255, 255));
	nextUnitText = NEW TextString(NULL, ksGlobalTextArray[GT_IGO_FT], 407, 394, 10, 0.50f, Font::HORIZJUST_LEFT, Font::VERTJUST_BOTTOM, color32(255, 255, 255, 255));

	dirIdx = 0;
	waveIdx = 0;
	tongueIdx = 0;

	fade = 1.0f;
	fadeDir = 0;
	state = STATE_NONE;
}
